// The realm atlas (website addition, original; owner's request, 2026-11-11): a full write-up for every realm, and the
// dimensions of the Inner Realm (whole worlds, each grown around one Law's anchor) and the Outer Realm (small pocket
// dimensions past the Astral, stranger the farther out). The build turns each dimension's materials into gathered
// materials, its gear into Blueprints, and shows all of it on the Realms page and in each realm's window.
//
// REALMS[name] = { ds: overview, travel: what changes for travelers, regions: [[name, line]], factions: [[name, line]],
//                  dangers: [line], hooks: [line] }
// DIMS: { n, realm, kind (a few words), law (the Law that holds it), ds, life (who lives there), dangers, travel,
//         hooks: [line], mats: [[name, grade 1-10, ore|herb|hide|fauna, description]],
//         gear: [[noun, category, profession, specialty, die or '', damage type or '', armor slot or '', level offset 0-9]] }

var REALMS = {
  'Human': {
    ds: 'The Mortal Realm, where mortals are born and where every god wants followers. It has almost no Laws of its own: nearly all of its magic is borrowed from the Runes of dead gods or bargained from living ones. Kingdoms rise and fall here on the bets of gods who never show their faces.',
    travel: 'Ordinary food, water and sleep work as expected. Thin places, where another realm presses close, are the usual doors out.',
    regions: [['Settled lands', 'Kingdoms, free cities and farmland, where most worship and most succession wars happen.'], ['The wilds', 'Forests, mountains and seas with ordinary beasts and the occasional stray from a higher realm.'], ['Thin places', 'Standing stones, drowned chapels and crossroads where the Astral, the Mysterious Realm or a fiend realm presses close.']],
    factions: [['Contractors', 'Mortals working for a god in secret, usually against each other.'], ['Temples', 'The open face of worship, rich in coin and quarrels.'], ['Guilds', 'Crafters, harvesters and mapmakers who sell what the realms give up.']],
    dangers: ['Other gods\' contractors.', 'Devils offering pacts that read well and end badly.', 'Things from higher realms that slip through thin places.'],
    hooks: ['A thin place has opened under a market town, and something is bartering through it.', 'Two temples both claim a newborn as their god\'s chosen; the baby has started speaking in Runes.']
  },
  'Mysterious': {
    ds: 'The in-between places that are not quite the Mortal Realm and not quite anywhere else: fey courts, elemental borders, mirror lands and the ghost roads. Rules here are older than the gods, and they are kept by bargain and custom rather than by Law.',
    travel: 'Time can run fast or slow; eating the local food can bind a traveler to a court. Names and promises carry real weight.',
    regions: [['The fey courts', 'Summer and winter halls whose seasons never end.'], ['The elemental borders', 'Where fire, water, earth and air spill out of their own planes.'], ['The ghost roads', 'Paths the dead walk between worlds, open on certain nights.']],
    factions: [['The courts', 'Fey nobles who trade in favors, names and years.'], ['Border wardens', 'Elementals and genies keeping their planes from bleeding into each other.']],
    dangers: ['Bargains that are kept exactly.', 'Lost time: a night of dancing can be a decade outside.', 'Elemental storms at the borders.'],
    hooks: ['A fey lord has won a city\'s name in a wager and the city is forgetting itself.', 'A ghost road is open on the wrong night and the dead are walking into a living town.']
  },
  'Hell': {
    ds: 'A realm as old as the Void and far more crowded, home to what is left of gods too broken or too cruel to hold a throne anywhere else. Hell runs on contract: every soul, debt and favor is written down, and the archdevils who keep the ledgers are the true powers here.',
    travel: 'Heat and brimstone wear on the unprotected. Any promise spoken aloud is binding, and the realm remembers it.',
    regions: [['The Burning Circles', 'Concentric layers of fire and iron, each ruled by an archdevil.'], ['The Ledger Halls', 'Endless archives where every contract ever signed is kept.'], ['The Ash Fields', 'Plains where broken souls work the forges.']],
    factions: [['The archdevils', 'Rulers of the circles, each bound by contracts older than mortals.'], ['The scribes', 'Devils who draft, keep and find loopholes in contracts.'], ['Soul brokers', 'Traders in mortal debts.']],
    dangers: ['Contracts with hidden clauses.', 'Fire that burns the soul as well as the body.', 'Devils who collect.'],
    hooks: ['A party member\'s ancestor signed something, and Hell has come to collect from the bloodline.', 'A stolen contract could free a thousand souls, or doom a kingdom.']
  },
  'Heaven': {
    ds: 'The mirror of Hell on the other side of the Mortal Realm, claimed by the gods who chose worship over cruelty. Heaven is beautiful and ordered, but it is also a court: angels rank by devotion, and politics are played in hymns.',
    travel: 'Lies are hard to speak aloud. Light is everywhere, and shadows are suspicious.',
    regions: [['The Choir Terraces', 'Tiered cities that sing their laws.'], ['The Gardens', 'Groves where the faithful dead rest.'], ['The Gates', 'Fortress-walls facing the Astral, always manned.']],
    factions: [['The choirs', 'Angelic hosts ranked by which god they sing for.'], ['The wardens of the Gates', 'Soldiers who fight what tries to enter.'], ['The quiet saints', 'Mortals raised to serve, many with doubts.']],
    dangers: ['Judgement: angels test intruders.', 'Zealots who see heresy everywhere.', 'Light that burns the unrepentant.'],
    hooks: ['An angel has fallen silent mid-hymn and the whole terrace is out of tune.', 'A saint begs the party to carry a message to Hell, in secret.']
  },
  'Chaos': {
    ds: 'The regions where the Law of Chaos has won outright and reality never settles. Ground melts into sky, colors change their taste, and a road leads somewhere new every time. Some creatures thrive here precisely because nothing stays.',
    travel: 'At each long rest, roll on the wild surge table. Maps fail; landmarks wander.',
    regions: [['The Shifting Sea', 'Land that moves like water.'], ['The Maybe Woods', 'Trees that may or may not be there.'], ['The Storm Spire', 'A tower of raw wild magic at the heart of the realm.']],
    factions: [['Wild sorcerers', 'Mortals who came to ride the chaos and stayed.'], ['The Unfixed', 'Natives with no single shape.']],
    dangers: ['Wild magic surges.', 'Terrain that changes mid-step.', 'Losing your shape, or your memories.'],
    hooks: ['A city from the Mortal Realm has fallen into Chaos whole, and it is starting to change.', 'Someone is trying to bring order to Chaos, and the realm is fighting back.']
  },
  'Abyss': {
    ds: 'The bottomless dark below Hell, where anything that falls keeps falling. Demon princes rule shifting layers carved out of the dark, each a reflection of its prince\'s hunger. It is the first realm beyond the power of most mortals, and it does not care who enters.',
    travel: 'Falling is constant somewhere; up and down are suggestions. Hunger grows faster than it should.',
    regions: [['The Falling Layers', 'Realms carved by demon princes, stacked without end.'], ['The Maw', 'A layer that is entirely mouth.'], ['The Drift', 'Debris of fallen worlds, still falling.']],
    factions: [['Demon princes', 'Each rules a layer shaped like its appetite.'], ['The fallen', 'Mortals and angels who fell in and adapted.']],
    dangers: ['Endless falls.', 'Demonic corruption.', 'Hunger that eats the mind.'],
    hooks: ['A prince offers safe passage through its layer for one small, specific thing.', 'A whole monastery is falling through the Abyss, still praying.']
  },
  'Inner Realm': {
    ds: 'The core that every other realm rests on, where the Laws are anchored to reality. Raw Law runs through it like ore through rock, and the strongest anchors are so heavy with Law that whole worlds have grown around them: the Inner Realm\'s dimensions. Each one is a complete world shaped by the Law it holds, from a land of knights and dragons to a steam-driven empire to an alien world under a violet sun. Damage an anchor and its Law weakens everywhere, so gods guard the Inner Realm closely and rarely speak of it.',
    travel: 'Each dimension follows its own Law first: fire burns hotter in a fire-anchored world, time runs differently in a time-anchored one. Moving between dimensions means walking the Law-veins or finding a door the anchor-wardens allow.',
    regions: [['The Law-veins', 'Tunnels where raw Law runs visibly through the rock; each vein carries one Law and links the dimensions it feeds.'], ['The Anchor Halls', 'Chambers holding the anchors of the most important Laws, each with its own warden.'], ['The dimensions', 'Whole worlds grown around anchors; thirteen are known and charted below.'], ['The Root', 'The deepest point, where every vein meets, said to sit against the Void.']],
    factions: [['Anchor-wardens', 'Ancient constructs whose makers no one remembers.'], ['The Cartographers of the Veins', 'Mortal and immortal mapmakers who sell routes between dimensions.'], ['Gods\' Fingers', 'Agents sent by gods to guard, or quietly steal, what is anchored here.']],
    dangers: ['Anchor-wardens attack anyone who touches a vein.', 'Raw Law can overwrite the mind of whoever gets too close.', 'Each dimension\'s natives defend their world\'s anchor, often without knowing what it is.'],
    hooks: ['A Law is weakening across the Mortal Realm, and someone is mining its vein.', 'Two dimensions\' veins have crossed: brass airships are appearing over a dragon\'s kingdom.', 'A god wants a specific anchor moved closer to its own realm.']
  },
  'Outer Realm': {
    ds: 'Whatever lies past the Astral, far enough out that no god has ever confirmed what is there. The Outer Realm is not one place but a scatter of small pocket dimensions, each a fragment of rule that broke off when the first gods died and drifted away from the Laws that should hold it. They are smaller than the Inner Realm\'s worlds, and much stranger: places where gravity is upside down, where sound is solid, where paper is the only matter. The farther out a pocket sits, the less sense it makes.',
    travel: 'Each pocket has one broken rule, and it applies to visitors at once. Pockets drift; a route that worked last month may now lead into empty Astral. Navigators charge a fortune.',
    regions: [['The Astral Shelf', 'The last stable ground before the pockets begin; outposts and navigators gather here.'], ['The pocket dimensions', 'Eighteen known pockets, charted below, and countless unknown ones.'], ['The Far Edge', 'Where pockets thin into nothing and the Watchers look in from outside.']],
    factions: [['Shelf navigators', 'The only people who reliably reach the pockets and return.'], ['Pocket natives', 'Beings made of their pocket\'s broken rule, rarely able to leave it.'], ['The Watchers', 'Huge eyes at the Far Edge; whether they are guarding or waiting, no one knows.']],
    dangers: ['A pocket\'s rule applies to you the moment you arrive.', 'Drifting routes that strand travelers.', 'Things from outside creation that notice visitors.'],
    hooks: ['A pocket has drifted into the Mortal Realm\'s sky, and its rule is leaking into the city below.', 'A navigator\'s chart shows a pocket that is not on any other map, and the navigator has vanished.']
  },
  'Void': {
    ds: 'The realm that Spin, Time, Gravity and Balance were pulled from, unclaimed by any god because nothing has ever lived there long enough to claim it. The Void is mostly absence: drifting wreckage, currents of pure motion, and things that formed around the scraps of Law the gods left behind.',
    travel: 'There is no up, no air unless you bring it, and time runs unevenly. Spells that rely on Spin, Time, Gravity or Balance behave unpredictably.',
    regions: [['The Drift', 'Wreckage of failed worlds, slowly turning.'], ['The Spin Currents', 'Rivers of motion that carry anything caught in them.'], ['The Stillwater', 'A region where time barely moves.'], ['The Balance Point', 'Where every force cancels, and nothing can be moved at all.']],
    factions: [['Fingers of the gods', 'The only regular visitors, sent to fetch Void materials.'], ['The Drifters', 'Hollow beings that formed in the wreckage.']],
    dangers: ['Being caught in a Spin Current.', 'Time slips: a minute here can be a year at home.', 'Starvation, suffocation and silence.'],
    hooks: ['A god\'s Finger has gone missing in the Drift with a cargo of Void-iron.', 'A world is drifting into the Void from somewhere else, still inhabited.']
  },
  'Inner Void': {
    ds: 'The deepest part of the Void, close to where Emptiness and Zero were first pulled from. Things here do not just lack: they remove. Whatever lives in the Inner Void makes things go missing, from sounds and colors to memories and names.',
    travel: 'Each day, a traveler forgets one thing unless protected. Light fades faster than it should; sound barely carries.',
    regions: [['The Hollows', 'Shapes of things that were removed, still outlined.'], ['The Quiet', 'Where sound has been eaten entirely.'], ['The Zero Gate', 'A place where counting stops.']],
    factions: [['The Absent', 'Beings who chose to forget themselves.'], ['Collectors', 'Creatures that hoard what others have lost.']],
    dangers: ['Forgetting.', 'Being erased.', 'Silence that kills.'],
    hooks: ['A city\'s name has been taken by something in the Inner Void, and no one can say where they live.', 'A collector offers to return a party member\'s lost memory, at a price.']
  },
  'Primordial': {
    ds: 'Where what is left of the original gods and dead progenitors lies. It is less a place you visit than a graveyard you trespass in: colossal bodies of gods form its mountains, their blood its seas. Everything here is older than the realms, and some of it is not entirely dead.',
    travel: 'The air is thick with the power of dead gods; every spell is louder and every wound slower to heal. The god-corpses have their own gravity.',
    regions: [['The Godfall', 'Plains where progenitors fell and lie still.'], ['The First Sea', 'Water older than any sea, home to the first beasts.'], ['The Cage of Iron', 'A prison no one remembers building.'], ['The Last Light', 'The glow of a god still dying.']],
    factions: [['Grave guardians', 'Constructs built by dying gods to guard their bodies.'], ['Relic-hunters', 'The bravest and greediest mortals alive.'], ['The Returning', 'Gods trying to reform from their own remains.']],
    dangers: ['God-beasts.', 'Divine remains that still act.', 'Pressure that crushes the unready.'],
    hooks: ['A dead god\'s heart has started beating again.', 'The Cage of Iron has a crack, and something inside is speaking.']
  }
};

